//Based on https://www.youtube.com/watch?v=f4s1h2YETNY
//inline comments may not be completely accurate.

// Gold Noise ©2015 dcerisano@standard3d.com
// - based on the Golden Ratio
// - uniform normalized distribution
// - fastest static noise generator function (also runs at low precision)
// - use with indicated fractional seeding method. 

float PHI = 1.61803398874989484820459;  // Φ = Golden Ratio   

float gold_noise(in vec2 xy, in float seed){
       return fract(tan(distance(xy*PHI, xy)*seed)*xy.x);
}

vec3 palette (float dist)
{
    //make a distance based colour gradient
    vec3 a = vec3(0.5,0.0,0.5);
    vec3 b = vec3(0.25,0.25,0.5);
    vec3 c = vec3(1.0,1.0,1.0);
    vec3 d = vec3(0.263,0.416,0.557);

    return a+b*cos(6.28318*(c*dist*d) );
}

float sdHexagon( in vec2 p, in float r )
{
    const vec3 k = vec3(-0.866025404,0.5,0.577350269);
    p = abs(p);
    p -= 2.0*min(dot(k.xy,p),0.0)*k.xy;
    p -= vec2(clamp(p.x, -k.z*r, k.z*r), r);
    return length(p)*sign(p.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //speed of ring movement (0.1 - 1.0 are good values)
    float speed = 0.1;
    //multiplier for number of colour rings (more rings more complex pattern)
    float ringmultiplier = 4.0;
    //width of colour regions (too high and you'll just get white as it uses additive colouring)
    float ringwidth = 8.0;
    //sort of smoothing between black and colour (0.1-0.4 are good)
    float smoothing = 0.4;
    //Iterations of fract (repeat of the pattern, set to 1 to see the basic pattern)
    float iter = 8.0;
    //Zoom amount, smaller = more zoomed in.
    float zoom = 1.;
    //noise seed
    float seed = 6502.;



    float myTime = iTime*0.5;

    // Centered aspect corrected normalized pixel coordinates (from -0.5 to 0.5)
    vec2 uv = ((fragCoord * 2.0 - iResolution.xy) / iResolution.y);

    //copy of uv before we mess with it in fract.
    vec2 uv0 = uv;
    float noise = gold_noise(fragCoord, seed) - ((sin(myTime * 0.5)*0.5) + 0.5);

    uv *= (zoom * sin(myTime*0.05));
    //initialise output colour (we add to this in the loop)
    vec3 outCol = vec3(0.0);

    for(float i = 0.0; i < iter; i++)
    {
        //repeat pattern
        uv = fract(uv * (1.25 + (sin((myTime * 0.1) * i))))-0.5;
        //uv = fract(uv)-0.5;

        //distance from centre 
        float dist = sdHexagon(uv, 0.25);

        // Time varying simple pixel color
        //vec3 col = 0.5 + 0.5 * cos((myTime*i*0.1) + uv.xyx + vec3(0,2,4));

        //distance/time varying pixel colour gradient
        vec3 col = palette(length(uv0) + myTime); //* (i*0.01));

        //time based distance with modifiers for speed, width, and number of rings
        dist = sin((dist - (myTime * speed)) * ringmultiplier * 2.0) / ringwidth;

        //absolute the distance to invert negative values
        dist = abs(dist);

        //take the inverse of the distance (effectively inverts what gets coloured in);
        dist = 0.001 / dist;

        //smoothstep colour to give clean edges.
        col = col * smoothstep(0.0, 0.5-smoothing, dist) * noise;

        outCol += col + dist;
    }

    // Output to screen
    fragColor = vec4(outCol,1.0);
}
